  3775  otError Mle::HandleDiscoveryResponse(const Message &aMessage, const Ip6::MessageInfo &aMessageInfo)
  3776  {
  3777      otError                       error    = OT_ERROR_NONE;
  3778      const otThreadLinkInfo *      linkInfo = static_cast<const otThreadLinkInfo *>(aMessageInfo.GetLinkInfo());
  3779      Tlv                           tlv;
  3780      MeshCoP::Tlv                  meshcopTlv;
  3781      MeshCoP::DiscoveryResponseTlv discoveryResponse;
  3782      MeshCoP::ExtendedPanIdTlv     extPanId;
  3783      MeshCoP::NetworkNameTlv       networkName;
  3784      MeshCoP::SteeringDataTlv      steeringData;
  3785      MeshCoP::JoinerUdpPortTlv     JoinerUdpPort;
  3786      otActiveScanResult            result;
  3787      uint16_t                      offset;
  3788      uint16_t                      end;
  3789      bool                          didCheckSteeringData = false;
  3790
  3791      LogMleMessage("Receive Discovery Response", aMessageInfo.GetPeerAddr());
  3792
  3793      VerifyOrExit(mDiscoverInProgress, error = OT_ERROR_DROP);
  3794
  3795      // find MLE Discovery TLV
  3796      VerifyOrExit(Tlv::GetOffset(aMessage, Tlv::kDiscovery, offset) == OT_ERROR_NONE, error = OT_ERROR_PARSE);
  3797      aMessage.Read(offset, sizeof(tlv), &tlv);
  3798
  3799      offset += sizeof(tlv);
  3800      end = offset + tlv.GetLength();
  3801
  3802      memset(&result, 0, sizeof(result));
  3803      result.mPanId   = linkInfo->mPanId;
  3804      result.mChannel = linkInfo->mChannel;
  3805      result.mRssi    = linkInfo->mRss;
  3806      result.mLqi     = linkInfo->mLqi;
  3807      aMessageInfo.GetPeerAddr().ToExtAddress(*static_cast<Mac::ExtAddress *>(&result.mExtAddress));
  3808
  3809      // process MeshCoP TLVs
  3810      while (offset < end)
  3811      {
  3812          aMessage.Read(offset, sizeof(meshcopTlv), &meshcopTlv);
  3813
  3814          switch (meshcopTlv.GetType())
  3815          {
  3816          case MeshCoP::Tlv::kDiscoveryResponse:
  3817              aMessage.Read(offset, sizeof(discoveryResponse), &discoveryResponse);
  3818              VerifyOrExit(discoveryResponse.IsValid(), error = OT_ERROR_PARSE);
  3819              result.mVersion  = discoveryResponse.GetVersion();
  3820              result.mIsNative = discoveryResponse.IsNativeCommissioner();
  3821              break;
  3822
  3823          case MeshCoP::Tlv::kExtendedPanId:
  3824              aMessage.Read(offset, sizeof(extPanId), &extPanId);
  3825              VerifyOrExit(extPanId.IsValid(), error = OT_ERROR_PARSE);
  3826              result.mExtendedPanId = extPanId.GetExtendedPanId();
  3827              break;
  3828
  3829          case MeshCoP::Tlv::kNetworkName:
  3830              aMessage.Read(offset, sizeof(networkName), &networkName);
  3831              memcpy(&result.mNetworkName, networkName.GetNetworkName(), networkName.GetNetworkNameLength());
  3832              result.mNetworkName.m8[networkName.GetNetworkNameLength()] = '\0';
  3833              break;
  3834
  3835          case MeshCoP::Tlv::kSteeringData:
  3836              aMessage.Read(offset, sizeof(steeringData), &steeringData);
  3837              VerifyOrExit(steeringData.IsValid(), error = OT_ERROR_PARSE);
  3838
  3839              if (mDiscoverEnableFiltering)
  3840              {
  3841                  VerifyOrExit((steeringData.GetBit(mDiscoverCcittIndex % steeringData.GetNumBits()) &&
  3842                                steeringData.GetBit(mDiscoverAnsiIndex % steeringData.GetNumBits())));
  3843              }
  3844
  3845              didCheckSteeringData         = true;
  3846              result.mSteeringData.mLength = steeringData.GetSteeringDataLength();
  3847              memcpy(result.mSteeringData.m8, steeringData.GetValue(), result.mSteeringData.mLength);
  3848
  3849              break;
  3850
  3851          case MeshCoP::Tlv::kJoinerUdpPort:
  3852              aMessage.Read(offset, sizeof(JoinerUdpPort), &JoinerUdpPort);
  3853              VerifyOrExit(JoinerUdpPort.IsValid(), error = OT_ERROR_PARSE);
  3854              result.mJoinerUdpPort = JoinerUdpPort.GetUdpPort();
  3855              break;
  3856
  3857          default:
  3858              break;
  3859          }
